import {objectValues} from '@jetbrains/teamcity-ui/dist/utils'
import type {EntryPointProps} from 'react-relay'
import {matchPath} from 'react-router'

import Routes, {getBaseRoute} from '../../../routes'
import {getLastAgentsPage} from '../../../utils/lastPage'
import Redirect from '../../common/Redirect/Redirect'

import {useRedirectAgentPageUrl} from './AgentsPages.hooks'
import type {AgentsPagesQueries} from './AgentsPages.queries'

export default function AgentsPages({queries}: EntryPointProps<AgentsPagesQueries, {}, {}, {}>) {
  const lastAgentsPage = getLastAgentsPage()

  const to = useRedirectAgentPageUrl(queries.agentTypes)

  if (
    lastAgentsPage == null ||
    objectValues(Routes).find(route => route !== Routes.BASE && matchPath(route, lastAgentsPage)) ==
      null
  ) {
    return <Redirect to={to} replace />
  }

  return <Redirect to={getBaseRoute(lastAgentsPage)} replace />
}
